use serde_json::Value;

pub fn solve(input: Value) -> Value {
    match input {
        Value::Array(arr) if arr.len() <= 1 => Value::Array(vec![]),
        Value::Array(arr) => {
            let mut result = Vec::new();
            for window in arr.windows(2) {
                if let (Value::Number(a), Value::Number(b)) = (window[0], window[1]) {
                    if let (Some(a), Some(b)) = (a.as_i64(), b.as_i64()) {
                        result.push(serde_json::Number::from(b - a));
                    }
                }
            }
            Value::Array(result)
        },
        _ => Value::Null,
    }
}
